const checkDomRemoval = function (mutations) {
  const isFocusedNodeRemoved = mutations.some(function (mutation) {
    const removedNodes = Array.from(mutation.removedNodes);
    return removedNodes.some(function (node) {
      return node === state.mostRecentlyFocusedNode;
    });
  });

  // Also check if any removed node was in the trap and focus has escaped.
  const focusEscaped = state.active && !state.paused && !state.containers.some(container => container.contains(document.activeElement));
  const removedNodeInTrap = mutations.some(function (mutation) {
    const removedNodes = Array.from(mutation.removedNodes);
    return removedNodes.some(function (node) {
      return state.containers.some(container => container.contains(node));
    });
  });

  // If the currently focused is removed then browsers will move focus to the
  // <body> element. If this happens, try to move focus back into the trap.
  if (isFocusedNodeRemoved || (removedNodeInTrap && focusEscaped)) {
    updateTabbableNodes();
    tryFocus(getInitialFocusNode());
  }
};
